488		// Same id repost -> idempotent with embedded result.
489		w, body = mergeBody(t, h, "doc", map[string]any{
490			"deviceId": "dev", "baseCursor": 1,
491			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
492		})
493		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
