160	// Closing reports whether the service has begun stopping. A woken subscription
161	// uses it to distinguish a termination signal from a commit.
162	func (s *Service) Closing() bool {
163		s.mu.Lock()
164		defer s.mu.Unlock()
165		return s.closed
166	}
