168	// interruptWaits wakes every parked long poll without closing the database, so
169	// an orderly shutdown drains waiting connections immediately (they answer 503)
170	// instead of holding shutdown hostage until their wait deadline. Committed
171	// state is untouched. Live subscriptions get one last wakeup as well; the
172	// connection layer re-checks the closed flag and finishes with a going-away
173	// close.
174	func (s *Service) InterruptWaits() {
175		s.mu.Lock()
176		s.closed = true
177		waits := s.waits
178		s.waits = map[string]map[uint64]chan struct{}{}
179		// Snapshot the live subscription channels without reaping the registry:
180		// unregister remains valid while handlers drain, so the WaitGroup in
181		// shutdown balances. New AddSubscription calls fail fast on closed.
182		var subChans []chan struct{}
183		for _, set := range s.subs {
184			for _, sub := range set {
185				subChans = append(subChans, sub.wakes)
186			}
187		}
188		s.mu.Unlock()
189		for _, set := range waits {
190			for _, ch := range set {
191				close(ch)
192			}
193		}
194		for _, ch := range subChans {
195			select {
196			case ch <- struct{}{}:
197			default:
198			}
199		}
200	}
201	
202	// waitSubscriptions blocks until every subscription handler has unregistered.
203	func (s *Service) WaitDrained() {
204		s.subWG.Wait()
205	}
